import { EnvironmentInjector, inject, Injectable } from '@angular/core';
import { HttpEvent, HttpResponse } from '@angular/common/http';
import { map, mergeMap, Observable } from 'rxjs';
import { AppConfigService } from '@common/context/config/app-config.service';
import { ClientService } from './client.service';

@Injectable({
  providedIn: 'root',
})
export class ApiService {
  private readonly environmentInjector = inject(EnvironmentInjector);
  public constructor(
    private readonly client: ClientService,
    private readonly appConfig: AppConfigService,
  ) {}

  get<T>(endpoint: string, params?: any): Observable<T> {
    return this.find(endpoint).pipe(
      mergeMap((conf) => {
        return this.client.get({ params, ...conf }) as Observable<T>;
      }),
    );
  }

  post<T>(endpoint: string, body: any, params?: any): Observable<T> {
    return this.find(endpoint).pipe(
      mergeMap((conf) => {
        return this.client.post({ body, params, ...conf }) as Observable<T>;
      }),
    );
  }

  download(endpoint: string, params?: any): Observable<HttpResponse<Blob>> {
    return this.find(endpoint).pipe(
      mergeMap((conf) => {
        return this.client.download({ params, ...conf });
      }),
    );
  }

  upload(endpoint: string, name: string, file: File, params?: any): Observable<HttpEvent<any>> {
    return this.find(endpoint).pipe(
      mergeMap((conf) => {
        return this.client.upload({ name, file, ...conf });
      }),
    );
  }

  put<T>(endpoint: string, body: any, params?: any): Observable<T> {
    return this.find(endpoint).pipe(
      mergeMap((conf) => {
        return this.client.put({ body, params, ...conf }) as Observable<T>;
      }),
    );
  }

  patch<T>(endpoint: string, body: any, params?: any): Observable<T> {
    return this.find(endpoint).pipe(
      mergeMap((conf) => {
        return this.client.patch({ body, params, ...conf }) as Observable<T>;
      }),
    );
  }

  delete<T>(endpoint: string, params?: any): Observable<T> {
    return this.find(endpoint).pipe(
      mergeMap((conf) => {
        return this.client.delete({ params, ...conf }) as Observable<T>;
      }),
    );
  }

  private find(url: string) {
    return this.appConfig['api'].pipe(
      map((apiConf) => {
        let headers = {} as any;
        let identity = '';
        let sendUid = false;
        if (apiConf) {
          Object.entries(apiConf).forEach(([key, api]: any[]) => {
            let matched = false;
            let prefix = '';
            if (url.startsWith('http://' + key)) {
              prefix = 'http://' + key;
            } else if (url.startsWith('https://' + key)) {
              prefix = 'https://' + key;
            } else if (url.startsWith(key)) {
              prefix = key;
            } else if (url.startsWith(api.url)) {
              prefix = api.url;
            }
            if (prefix.length > 0) {
              matched = true;
            }
            if (matched) {
              if (api.url) {
                url = api.url + url.substring(prefix.length);
              }
              identity = api.identity;
              sendUid = !!api.identity;
              if (api.headers) {
                for (const i of Object.keys(api.headers)) {
                  headers[i] = api.headers[i];
                }
              }
            }
          });
        }
        return { url: url, headers: headers, identity: identity, withIdentity: sendUid };
      }),
    );
  }
}
